go-back-n-arq.pseudocode:
def gbn_sender(frames, N):
    base = next_seq = 0  # 윈도 시작, 다음 송신 번호
    while base < len(frames):
        # 윈도 안이면 연속 송신
        while next_seq < min(base + N, len(frames)):
            send(next_seq, frames[next_seq])
            if base == next_seq:
                start_timer()  # 가장 오래된 미확인 프레임 기준
            next_seq += 1
        ev = wait_event()
        if ev.kind == 'ack' and ev.ack > base: # 누적 ACK: ack 직전까지 모두 확인
            base = ev.ack
            if base == next_seq:
                stop_timer()
            else:
                start_timer()
        elif ev.kind == 'timeout':  # 손실 → base부터 전부 재전송
            next_seq = base
    # 실제 순번은 mod 2^m, 송신 윈도 N ≤ 2^m − 1

def gbn_receiver():
    expected = 0
    while True:
        seq, data, ok = receive()
        # 순서 맞는 프레임만 수용 (수신 윈도 1)
        if ok and seq == expected:
            deliver(data)
            expected += 1
        send_ack(expected)  # 누적 ACK (어긋난 프레임은 폐기)

goal-seeking-analysis.pseudocode:
def goal_seek(model, target, lo, hi, tol=1e-6):
    # model(x)가 x에 대해 단조 증가라고 가정 (이분 탐색)
    for _ in range(100):
        mid = (lo + hi) / 2
        if model(mid) < target:
            lo = mid  # 목표 미달 → 입력 증가
        else:
            hi = mid
        if hi - lo < tol:
            break
    return (lo + hi) / 2

# 이익 = (가격 - 변동비) × Q - 고정비
profit = lambda q: (10_000 - 6_000) * q - 200_000_000
q = goal_seek(profit, 100_000_000, 0, 1e6)  # → 75,000개

gossip-protocol.pseudocode:
class Node:
    def __init__(self, peers):
        self.peers = peers  # 멤버십 목록
        self.state = {}  # {키: (값, 버전)}

    def merge(self, other_state):
        for key, (value, ver) in other_state.items():
            mine = self.state.get(key)
            if mine is None or ver > mine[1]:  # 더 최신 버전만 채택
                self.state[key] = (value, ver)

    def gossip_round(self, fanout):
        # 임의 이웃 k개
        for peer in random_sample(self.peers, fanout):
            peer.merge(self.state)  # push: 내 상태 전달
            self.merge(peer.state)  # pull: 상대 상태 병합

def run(node, interval):
    while True:
        node.gossip_round(fanout=3)
        sleep(interval)  # 주기 반복 → 최종적 일관성

goto-table.pseudocode:
def lr_parse(tokens, ACTION, GOTO):
    stack = [0]  # 상태 스택
    tokens = tokens + ['$']
    i = 0
    while True:
        s, a = stack[-1], tokens[i]
        act = ACTION[s].get(a)
        if act is None:
            return 'error'
        kind, val = act
        if kind == 'shift':
            stack.append(val)
            i += 1
        elif kind == 'reduce':
            lhs, rhs_len = val  # A → β, |β|
            del stack[len(stack) - rhs_len:]
            t = stack[-1]  # 축소 후 노출된 상태
            stack.append(GOTO[t][lhs])  # GOTO 참조
        else:
            return 'accept'
